import {
  Box,
  Button,
  Card,
  CardContent,
  CardMedia,
  Chip,
  Container,
  Grid,
  Link,
  Stack,
  Typography,
} from "@mui/material";
import masterData from "../../data/masterData.json";
import {
  ArrowForwardIcon,
  LocationOnOutlinedIcon,
  ScheduleOutlinedIcon,
} from "../../utils/iconMap";
import type { Program } from "../../types/fellowship";

interface FeaturedProgramsSectionProps {
  onLearnMore: (programId: string) => void;
  onViewAll?: () => void;
  programs?: Program[];
  title?: string;
  showViewAll?: boolean;
}

export default function FeaturedProgramsSection({
  onLearnMore,
  onViewAll,
  programs,
  title,
  showViewAll = true,
}: FeaturedProgramsSectionProps) {
  const { sections } = masterData;
  const list =
    programs ||
    (masterData.programs.filter((p) => p.featured) as Program[]);

  return (
    <Box sx={{ py: { xs: 5, md: 8 }, bgcolor: "#FAFBFD" }}>
      <Container maxWidth="lg">
        <Stack
          direction="row"
          justifyContent="space-between"
          alignItems="center"
          sx={{ mb: 3 }}
        >
          <Typography
            variant="h4"
            sx={{ fontWeight: 800, color: "#0A2540", fontSize: { xs: "1.4rem", md: "2rem" } }}
          >
            {title || sections.featured.title}
          </Typography>
          {showViewAll && (
            <Link
              component="button"
              underline="none"
              onClick={onViewAll}
              sx={{
                display: "inline-flex",
                alignItems: "center",
                gap: 0.5,
                color: "primary.main",
                fontWeight: 600,
                fontSize: { xs: 13, md: 15 },
                cursor: "pointer",
              }}
            >
              {sections.featured.viewAll} <ArrowForwardIcon sx={{ fontSize: 16 }} />
            </Link>
          )}
        </Stack>

        <Grid container spacing={2.5}>
          {list.map((program) => (
            <Grid key={program.id} size={{ xs: 12, sm: 6, md: 4 }}>
              <Card
                sx={{
                  height: "100%",
                  display: "flex",
                  flexDirection: "column",
                  borderRadius: 2,
                  overflow: "hidden",
                }}
              >
                <Box sx={{ position: "relative" }}>
                  <CardMedia
                    component="img"
                    height="180"
                    image={program.image}
                    alt={program.title}
                    sx={{ objectFit: "cover" }}
                  />
                  {program.isPopular && (
                    <Chip
                      label="Most Popular"
                      size="small"
                      sx={{
                        position: "absolute",
                        top: 12,
                        left: 12,
                        bgcolor: "primary.main",
                        color: "#fff",
                        fontWeight: 600,
                        fontSize: 12,
                      }}
                    />
                  )}
                </Box>
                <CardContent sx={{ flex: 1, display: "flex", flexDirection: "column", p: 2.5 }}>
                  <Typography sx={{ fontWeight: 700, color: "#0A2540", mb: 1.5, fontSize: 16 }}>
                    {program.title}
                  </Typography>
                  <Stack direction="row" spacing={2} sx={{ mb: 1 }}>
                    <Stack direction="row" spacing={0.5} alignItems="center">
                      <ScheduleOutlinedIcon sx={{ fontSize: 16, color: "text.secondary" }} />
                      <Typography variant="body2" color="text.secondary">
                        {program.duration}
                      </Typography>
                    </Stack>
                    <Stack direction="row" spacing={0.5} alignItems="center">
                      <LocationOnOutlinedIcon sx={{ fontSize: 16, color: "text.secondary" }} />
                      <Typography variant="body2" color="text.secondary">
                        {program.location}
                      </Typography>
                    </Stack>
                  </Stack>
                  <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                    Conducted at {program.hospital}
                  </Typography>
                  <Button
                    variant="contained"
                    fullWidth
                    endIcon={<ArrowForwardIcon />}
                    onClick={() => onLearnMore(program.id)}
                    sx={{ mt: "auto" }}
                  >
                    Learn More
                  </Button>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Container>
    </Box>
  );
}
